export const SKILL_MAP = new Map(SKILLS.map((s) => [s.id, s]));

// dependents: which skills each skill unlocks (for "next recommended" + blocking priority)
export const DEPENDENTS = new Map<string, string[]>();
SKILLS.forEach((s) => DEPENDENTS.set(s.id, []));
SKILLS.forEach((s) => s.prereq.forEach((p) => DEPENDENTS.get(p)?.push(s.id)));

